    radial-gradient(120% 90% at 50% 45%, transparent 55%, rgba(0, 0, 0, 0.6) 100%),
    linear-gradient(180deg, #060607 0%, #09090b 55%, #0d0c0f 100%) !important;
  background-size: 160px 160px, 100% 100%, 100% 100% !important;
  background-repeat: repeat, no-repeat, no-repeat !important;
}

