  background-size: 460px 460px, 360px 360px;
  background-repeat: repeat, no-repeat;
  background-position: 30px 20px, left -150px top -140px;
  -webkit-mask-image: linear-gradient(90deg, #000 0%, #000 3%, rgba(0, 0, 0, 0.16) 11%, rgba(0, 0, 0, 0.16) 80%, #000 96%, #000 100%);
